class Dog {
  public string Name;
  public Dog() { Name = "Buddy"; }
}
static void Main() {
  Dog dog = new Dog();
  Console.WriteLine(dog.Name);
}

class Person {
  public string Name;
  public Person(string n) { Name = n; }
}
static void Main() {
  Person p = new Person("Aris");
  Console.WriteLine(p.Name);
}
